package com.afirma.assina;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import org.springframework.core.io.ClassPathResource;
import tools.jackson.databind.ObjectMapper;

class RegrasAutenticaTest {
 private final ObjectMapper json=new ObjectMapper();
 @Test void compilaOsMesmosVetoresDoCodigoNodeDeProducao()throws Exception{var raiz=json.readTree(new ClassPathResource("autentica-compilador-origem.json").getInputStream());for(var caso:raiz.path("casos")){var fluxo=json.treeToValue(caso.path("fluxo"),Map.class);assertEquals(caso.path("esperado"),json.valueToTree(CompiladorBotAutentica.compilar(fluxo)));}}
 @Test void personalizaContatosSemExecutarCodigoOuPerderSaudacaoGlobal(){assertEquals("Bom dia, Ana; {{Saudação}}",DisparosAutentica.personalizar("Bom dia, {{nome}}; {{Saudação}}",Map.of("nome","Ana"),List.of(),false));assertEquals("Ana",DisparosAutentica.personalizar("{{1}}",Map.of("nome","Ana"),List.of(Map.of("id",1,"valor","nome")),true));}
 @Test void normalizaTelefonesNacionaisEInternacionais(){assertEquals("5511999990000",DisparosAutentica.telefone("(11) 99999-0000"));assertEquals("351912345678",DisparosAutentica.telefone("+351 912345678"));assertEquals("",DisparosAutentica.telefone(null));}
 @Test void respeitaDiasEHorarioInclusivoDoDisparo(){var d=new HashMap<String,Object>(Map.of("DisparoMassaDiasEnvio","1,2,3,4,5","DisparoMassaHoraReinicio","08:00","DisparoMassaUltimoHorario","18:00"));ZoneId z=ZoneId.of("America/Sao_Paulo");assertTrue(DisparosAutentica.horario(d,ZonedDateTime.of(2026,11,2,8,0,0,0,z)));assertTrue(DisparosAutentica.horario(d,ZonedDateTime.of(2026,11,2,18,0,0,0,z)));assertFalse(DisparosAutentica.horario(d,ZonedDateTime.of(2026,11,2,18,1,0,0,z)));assertFalse(DisparosAutentica.horario(d,ZonedDateTime.of(2026,11,1,10,0,0,0,z)));}
 @Test void compoeTemplateComCabecalhoExemplosRodapeEBotoes(){var r=new HashMap<String,Object>();r.put("MensagemTemplateCabecalhoTipo","Texto");r.put("MensagemTemplateCabecalhoConteudo",Map.of("Texto","Olá, {{1}}"));r.put("MensagemTemplateCabecalhoVariaveis",List.of(Map.of("Valor","Ana")));r.put("MensagemTemplateCorpo","Seu contrato {{1}} está pronto.");r.put("MensagemTemplateCorpoVariaveis",List.of(Map.of("Valor","123")));r.put("MensagemTemplateRodape","Equipe");r.put("MensagemTemplateBotoes",List.of(Map.of("Tipo","quick-reply","Texto","Confirmar")));var cs=TemplatesMetaAutentica.componentes(r);assertEquals(4,cs.size());assertEquals("HEADER",cs.get(0).get("type"));assertEquals(Map.of("body_text",List.of(List.of("123"))),cs.get(1).get("example"));assertEquals(List.of(Map.of("type","QUICK_REPLY","text","Confirmar")),cs.get(3).get("buttons"));}
 @Test void emiteSessoesDiferentesMesmoNoMesmoSegundo()throws Exception{String a=TokensEmpresaAssineai.emitir("usuario:1","segredo-teste"),b=TokensEmpresaAssineai.emitir("usuario:1","segredo-teste");assertNotEquals(a,b);assertEquals("usuario:1",TokensEmpresaAssineai.ler(a,"segredo-teste"));}
 @Test void agendaDiaSeguintePermitidoSemBloquearOutrasCampanhas(){var d=new HashMap<String,Object>(Map.of("DisparoMassaDiasEnvio","1,2,3,4,5","DisparoMassaHoraReinicio","08:00","DisparoMassaUltimoHorario","18:00"));var sexta=ZonedDateTime.of(2026,11,6,19,0,0,0,ZoneId.of("America/Sao_Paulo"));assertEquals(LocalDate.of(2026,11,9),DisparosAutentica.proximaJanela(d,sexta,false).toLocalDate());assertEquals(8,DisparosAutentica.proximaJanela(d,sexta,false).getHour());}
 @Test void preservaFormatoDeBotoesEListasDaMeta(){var b=MensagensInterativasAutentica.montar(Map.of("Tipo","Botao","Texto","Confirma?","Botoes",List.of(Map.of("Tipo","reply","Id",1,"Texto","Sim"))));assertEquals("button",b.get("type"));assertEquals(Map.of("text","Confirma?"),b.get("body"));var l=MensagensInterativasAutentica.montar(Map.of("Tipo","Lista","Texto","Escolha","Lista",Map.of("Texto","Ver opções","Itens",List.of(Map.of("Titulo","Contratos","Itens",List.of(Map.of("Id",1,"Titulo","Assinar","Descricao","")))))));assertEquals("list",l.get("type"));}
}
